1	// Package types — see reviewer.go for package-level rationale.
2	//
3	// template.go provides ReviewerTemplate, a struct that implements
4	// AgentReviewer using two caller-supplied functions: BuildCmd (per-agent
5	// argv/env construction) and Parser (per-agent stdout-to-Event stream).
6	//
7	// All three currently-supported agents (claude-code, codex, gemini-cli)
8	// share the Start/Process/Wait/Events scaffolding. Only the build-cmd
9	// step and the stdout parser genuinely differ. The template owns the
10	// shared lifecycle (spawn → pipe stdout → run parser → forward events
11	// → close on exit); each agent supplies the two unique pieces.
12	package types
13	
14	import (
15		"context"
16		"errors"
17		"fmt"
18		"io"
19		"os/exec"
20		"strings"
21	)
22	
23	const maxProcessStderrBytes = 64 * 1024
24	
25	// ReviewerTemplate implements AgentReviewer for agents whose only per-agent
26	// quirks are argv/env construction and stdout parsing. Both fields must be
27	// set before Start is called; nil values cause Start to panic immediately.
28	type ReviewerTemplate struct {
29		// AgentName is returned by Name(). Stable identifier per agent.
30		AgentName string
31	
32		// BuildCmd constructs the *exec.Cmd to spawn the agent process,
33		// including argv, stdin (if any), and ENTIRE_REVIEW_* env vars.
34		// The command MUST NOT have started yet; the template will call Start.
35		BuildCmd func(ctx context.Context, cfg RunConfig) *exec.Cmd
36	
37		// Parser converts the agent's stdout stream into a sequence of Events.
38		// The returned channel must close when stdout closes. Implementations
39		// must emit Started first, Finished{Success: ...} or RunError last,
40		// and check scanner.Err() before emitting Finished{Success: true}.
41		Parser func(stdout io.Reader) <-chan Event
42	}
43	
44	// Compile-time check.
45	var _ AgentReviewer = (*ReviewerTemplate)(nil)
46	
47	// Name returns the agent's stable identifier.
48	func (t *ReviewerTemplate) Name() string { return t.AgentName }
49	
50	// Start spawns the agent process, wires stdout through the parser, and
51	// returns a Process whose Events channel streams the parsed event sequence.
52	//
53	// Returns ErrTemplateMisconfigured if AgentName, BuildCmd, or Parser is unset,
54	// or if BuildCmd returns nil. These are programmer errors but failing fast
55	// with a typed error is friendlier than a downstream nil deref — and it
56	// keeps Start from panicking inside a multi-agent fan-out (CU8) where one
57	// misconfigured template would otherwise kill the whole run.
58	func (t *ReviewerTemplate) Start(ctx context.Context, cfg RunConfig) (Process, error) {
59		if t.AgentName == "" {
60			return nil, fmt.Errorf("ReviewerTemplate.Start: %w (empty AgentName)", ErrTemplateMisconfigured)
61		}
62		if t.BuildCmd == nil {
63			return nil, fmt.Errorf("ReviewerTemplate.Start: %w (nil BuildCmd for agent %q)", ErrTemplateMisconfigured, t.AgentName)
64		}
65		if t.Parser == nil {
66			return nil, fmt.Errorf("ReviewerTemplate.Start: %w (nil Parser for agent %q)", ErrTemplateMisconfigured, t.AgentName)
67		}
68		cmd := t.BuildCmd(ctx, cfg)
69		if cmd == nil {
70			return nil, fmt.Errorf("ReviewerTemplate.Start: %w (BuildCmd returned nil for agent %q)", ErrTemplateMisconfigured, t.AgentName)
71		}
72		stdout, err := cmd.StdoutPipe()
73		if err != nil {
74			return nil, fmt.Errorf("%s: stdout pipe: %w", t.AgentName, err)
75		}
76		stderr, err := cmd.StderrPipe()
77		if err != nil {
78			return nil, fmt.Errorf("%s: stderr pipe: %w", t.AgentName, err)
79		}
80		if err := cmd.Start(); err != nil {
81			return nil, fmt.Errorf("%s: start: %w", t.AgentName, err)
82		}
83		p := &templateProcess{
84			ctx:        ctx,
85			agentName:  t.AgentName,
86			cmd:        cmd,
87			events:     make(chan Event, 32),
88			stderr:     &boundedStderrBuffer{limit: maxProcessStderrBytes},
89			stderrDone: make(chan struct{}),
90		}
91		go p.run(stdout, t.Parser)
92		go p.captureStderr(stderr)
93		return p, nil
94	}
95	
96	// ErrTemplateMisconfigured is returned by ReviewerTemplate.Start when one of
97	// the required fields (AgentName, BuildCmd, Parser) is unset, or when
98	// BuildCmd returns nil. Use errors.Is to detect this in tests or higher
99	// layers (e.g., a multi-agent orchestrator that needs to skip a misconfigured
100	// agent rather than crashing the whole run).
101	var ErrTemplateMisconfigured = errors.New("ReviewerTemplate misconfigured")
102	
103	// templateProcess is the shared Process implementation for ReviewerTemplate.
104	type templateProcess struct {
105		ctx        context.Context
106		agentName  string
107		cmd        *exec.Cmd
108		events     chan Event
109		stderr     *boundedStderrBuffer
110		stderrDone chan struct{}
111	}
112	
113	// Events returns the channel that streams parsed events from the agent process.
114	func (p *templateProcess) Events() <-chan Event { return p.events }
115	
116	// Wait returns the agent process's exit error with bounded stderr diagnostics.
117	//
118	// Per CU2's Process contract: nil on clean exit (exit code 0); ctx.Err()
119	// on cancellation; ProcessError wrapping *exec.ExitError on non-zero exit
120	// with stderr; other types for I/O or pipe failures. ProcessError implements
121	// Unwrap so callers can use errors.As and errors.Is to classify.
122	func (p *templateProcess) Wait() error {
123		if p.stderrDone != nil {
124			<-p.stderrDone
125		}
126		err := p.cmd.Wait()
127		if err != nil && p.ctx.Err() != nil {
128			return p.ctx.Err() //nolint:wrapcheck // preserve Process cancellation contract
129		}
130		if err != nil {
131			if stderr := p.stderr.String(); stderr != "" {
132				return &ProcessError{AgentName: p.agentName, Err: err, Stderr: stderr}
133			}
134		}
135		return err //nolint:wrapcheck // interface boundary; classifyStatus needs raw type
136	}
137	
138	func (p *templateProcess) run(stdout io.Reader, parser func(io.Reader) <-chan Event) {
139		defer close(p.events)
140		for ev := range parser(stdout) {
141			p.events <- ev
142		}
143	}
144	
145	func (p *templateProcess) captureStderr(stderr io.Reader) {
146		defer close(p.stderrDone)
147		_, _ = io.Copy(p.stderr, stderr) //nolint:errcheck // stderr is best-effort diagnostic context
148	}
149	
150	// ProcessError wraps a process failure with bounded stderr diagnostics.
151	// Unwrap preserves the underlying error, so callers can still use errors.As
152	// for *exec.ExitError or errors.Is for lower-level sentinels.
153	type ProcessError struct {
154		AgentName string
155		Err       error
156		Stderr    string
157	}
158	
159	func (e *ProcessError) Error() string {
160		if e.Stderr == "" {
161			return fmt.Sprintf("%s: %v", e.AgentName, e.Err)
162		}
163		return fmt.Sprintf("%s: %v: stderr: %s", e.AgentName, e.Err, e.Stderr)
164	}
165	
166	func (e *ProcessError) Unwrap() error { return e.Err }
167	
168	type boundedStderrBuffer struct {
169		limit     int
170		buf       []byte
171		truncated bool
172	}
173	
174	func (b *boundedStderrBuffer) Write(p []byte) (int, error) {
175		if b.limit <= 0 {
176			b.truncated = true
177			return len(p), nil
178		}
179		remaining := b.limit - len(b.buf)
180		if remaining > 0 {
181			if len(p) <= remaining {
182				b.buf = append(b.buf, p...)
183			} else {
184				b.buf = append(b.buf, p[:remaining]...)
185				b.truncated = true
186			}
187		} else if len(p) > 0 {
188			b.truncated = true
189		}
190		return len(p), nil
191	}
192	
193	func (b *boundedStderrBuffer) String() string {
194		out := strings.TrimSpace(string(b.buf))
195		if out == "" {
196			return ""
197		}
198		if b.truncated {
199			return out + "\n[stderr truncated]"
200		}
201		return out
202	}
