245	func composeReviewFixPrompt(manifest LocalReviewManifest, sources []reviewFixSource) string {
246		var b strings.Builder
247		b.WriteString("Fix only the selected review findings.\n")
248		b.WriteString("Do not rewrite unrelated code. Run targeted tests where practical, then report what changed and what verification passed.\n")
249		if manifest.StartingSHA != "" {
250			fmt.Fprintf(&b, "\nReviewed commit: %s\n", manifest.StartingSHA)
251		}
252		if manifest.WorktreePath != "" {
253			fmt.Fprintf(&b, "Worktree: %s\n", manifest.WorktreePath)
254		}
255		for _, source := range sources {
256			if strings.TrimSpace(source.Output) == "" {
257				continue
258			}
259			fmt.Fprintf(&b, "\n## %s\n\n%s\n", source.Label, strings.TrimSpace(source.Output))
260		}
261		return strings.TrimSpace(b.String()) + "\n"
262	}
263	
264	func reviewFixSourcesForManifest(manifest LocalReviewManifest) []reviewFixSource {
265		sources := make([]reviewFixSource, 0, len(manifest.Sources)+1)
266		for _, source := range manifest.Sources {
267			if strings.TrimSpace(source.Output) == "" {
268				continue
269			}
270			label := source.Label
271			if label == "" {
272				label = source.Agent
273			}
274			sources = append(sources, reviewFixSource{
275				Kind:   reviewFixSourceAgent,
276				Agent:  source.Agent,
277				Label:  label + " findings",
278				Output: source.Output,
279			})
280		}
281		if strings.TrimSpace(manifest.AggregateOutput) != "" {
282			sources = append(sources, reviewFixSource{
283				Kind:   reviewFixSourceAggregate,
284				Label:  "Aggregate summary",
285				Output: manifest.AggregateOutput,
286			})
287		} else if len(sources) > 1 {
288			sources = append(sources, reviewFixSource{
289				Kind:      reviewFixSourceAggregate,
290				Label:     "Aggregate findings",
291				Output:    selectedSourcesOutput(sources),
292				Synthetic: true,
293			})
294		}
295		return sources
296	}
