363	func extractSourceFindings(source reviewFixSource, sourceIndex int) []reviewFinding {
364		lines := strings.Split(source.Output, "\n")
365		var findings []reviewFinding
366		var current *reviewFinding
367		for _, line := range lines {
368			trimmed := strings.TrimSpace(line)
369			title, ok := reviewFindingTitle(trimmed)
370			if ok {
371				if current != nil {
372					findings = append(findings, *current)
373				}
374				current = &reviewFinding{
375					ID:    fmt.Sprintf("source-%d-%d", sourceIndex, len(findings)+1),
376					Title: source.Label + ": " + stringutil.TruncateRunes(title, 90, "..."),
377					Body:  title,
378				}
379				continue
380			}
381			if current != nil {
382				current.Body = strings.TrimSpace(current.Body + "\n" + line)
383			}
384		}
385		if current != nil {
386			findings = append(findings, *current)
387		}
388		return findings
389	}
