391	func reviewFindingTitle(line string) (string, bool) {
392		line = strings.TrimLeft(line, "#*- \t")
393		line = strings.TrimSpace(line)
394		if len(line) < 3 {
395			return "", false
396		}
397		if isSeverityNumberedTitle(line) {
398			return line, true
399		}
400		lower := strings.ToLower(line)
401		for _, prefix := range []string{"blocker", "critical", "high", "medium", "low"} {
402			if strings.HasPrefix(lower, prefix+":") || strings.HasPrefix(lower, prefix+" -") || strings.HasPrefix(lower, prefix+".") {
403				return line, true
404			}
405		}
406		return "", false
407	}
