409	func isSeverityNumberedTitle(line string) bool {
410		if len(line) < 3 {
411			return false
412		}
413		switch line[0] {
414		case 'H', 'M', 'L':
415		default:
416			return false
417		}
418		return line[1] >= '0' && line[1] <= '9' && (line[2] == '.' || line[2] == ')')
419	}
