447	func resolveReviewFixAgent(ctx context.Context, cmd *cobra.Command, sources []reviewFixSource, agentOverride string) (string, error) {
448		if agentOverride != "" {
449			return agentOverride, nil
450		}
451		if agentName, ok := reviewFixAgentFromSelectedSources(sources); ok {
452			return agentName, nil
453		}
454	
455		s, err := settings.Load(ctx)
456		if err != nil {
457			return "", fmt.Errorf("load review fix settings: %w", err)
458		}
459		choices := reviewFixAgentChoices(s.Review)
460		if len(choices) == 0 {
461			choices = reviewFixAgentChoicesFromSources(sources)
462		}
463		switch len(choices) {
464		case 0:
465			return "", errors.New("cannot determine fix agent; rerun with --agent")
466		case 1:
467			return choices[0].Name, nil
468		}
469		if pick, ok := savedReviewFixAgentPick(choices, s.ReviewFixAgent); ok {
470			return pick, nil
471		}
472	
473		if !interactive.IsTerminalWriter(cmd.OutOrStdout()) || !interactive.CanPromptInteractively() {
474			return "", errors.New("multiple fix agents configured; rerun with --agent or run `entire review --edit`")
475		}
476	
477		picked, err := promptForReviewFixAgent(ctx, choices, s.ReviewFixAgent)
478		if err != nil {
479			return "", err
480		}
481		if err := SaveReviewFixAgent(ctx, picked); err != nil {
482			return "", err
483		}
484		return picked, nil
485	}
