588	func launchReviewFixAgent(ctx context.Context, agentName string, prompt string) error {
589		ag, err := agent.Get(agenttypes.AgentName(agentName))
590		if err != nil {
591			return fmt.Errorf("resolve fix agent %s: %w", agentName, err)
592		}
593		launcher, ok := agent.LauncherFor(ag.Name())
594		if !ok {
595			return fmt.Errorf("agent %s cannot be launched for review fixes", agentName)
596		}
597		cmd, err := launcher.LaunchCmd(ctx, prompt)
598		if err != nil {
599			return fmt.Errorf("build fix command: %w", err)
600		}
601		cmd.Env = withoutReviewEnv(cmd.Env)
602		if len(cmd.Env) == 0 {
603			cmd.Env = withoutReviewEnv(os.Environ())
604		}
605		if err := cmd.Run(); err != nil {
606			if errors.Is(err, context.Canceled) {
607				return fmt.Errorf("fix agent cancelled: %w", err)
608			}
609			var exitErr *exec.ExitError
610			if errors.As(err, &exitErr) {
611				return fmt.Errorf("fix agent exited with status %d: %w", exitErr.ExitCode(), err)
612			}
613			return fmt.Errorf("run fix agent: %w", err)
614		}
615		return nil
616	}
