1096	// adoptReviewEnv tags the session as a review session when ENTIRE_REVIEW_*
1097	// env vars are present on the current process. `entire review` sets these
1098	// vars on the spawned agent process; the lifecycle hook (a child of the agent)
1099	// inherits them naturally. Agent and starting-SHA checks protect against stale
1100	// ENTIRE_REVIEW_* values inherited from a parent shell or a nested invocation.
1101	//
1102	// Adoption is idempotent: if state.Kind is already set (subsequent turns of
1103	// a review session) the function returns without modifying state.
1104	//
1105	// Failure modes are silent at the user level but logged for diagnostics:
1106	//   - EnvSession unset or not "1": not a review session; return, no tagging.
1107	//   - EnvAgent does not match the hook agent: leave session untagged.
1108	//   - EnvStartingSHA does not match the session base commit: leave untagged.
1109	//   - EnvSkills malformed JSON: log warning, leave session untagged to avoid
1110	//     corrupting metadata with junk data.
1111	func adoptReviewEnv(ctx context.Context, state *session.State, expectedAgent string) {
1112		// Already tagged — don't re-apply on subsequent turns.
1113		if state.Kind != "" {
1114			return
1115		}
1116		if envSession := os.Getenv(review.EnvSession); envSession != "1" {
1117			logging.Debug(ctx, "review env adoption skipped: ENTIRE_REVIEW_SESSION is not \"1\"",
1118				slog.String("expected_agent", expectedAgent),
1119				slog.String("observed_value", envSession))
1120			return
1121		}
1122		envAgent := os.Getenv(review.EnvAgent)
1123		if envAgent != expectedAgent {
1124			logging.Warn(ctx, "review env adoption skipped: agent mismatch",
1125				slog.String("env_agent", envAgent),
1126				slog.String("hook_agent", expectedAgent))
1127			return
1128		}
1129		startingSHA := os.Getenv(review.EnvStartingSHA)
1130		if startingSHA == "" || state.BaseCommit == "" || startingSHA != state.BaseCommit {
1131			logging.Warn(ctx, "review env adoption skipped: starting SHA mismatch",
1132				slog.String("env_starting_sha", startingSHA),
1133				slog.String("state_base_commit", state.BaseCommit))
1134			return
1135		}
1136		skills, err := review.DecodeSkills(os.Getenv(review.EnvSkills))
1137		if err != nil {
1138			logging.Warn(ctx, "review env adoption failed: invalid skills JSON",
1139				slog.String("err", err.Error()))
1140			return
1141		}
1142		state.Kind = session.KindAgentReview
1143		state.ReviewSkills = skills
1144		state.ReviewPrompt = os.Getenv(review.EnvPrompt)
1145		logging.Debug(ctx, "adopted review env",
1146			slog.String("agent", envAgent),
1147			slog.Int("skill_count", len(skills)))
1148	}
