61	// exit, or a wrapped error on cancellation / non-zero exit. Output / input
62	// are connected to the calling process's stdio so the user can interact
63	// with the fix session in their terminal.
64	func LaunchFixAgent(ctx context.Context, agentName string, prompt string) error {
65		ag, err := agent.Get(agenttypes.AgentName(agentName))
66		if err != nil {
67			return fmt.Errorf("resolve fix agent %s: %w", agentName, err)
68		}
69		launcher, ok := agent.LauncherFor(ag.Name())
70		if !ok {
71			return fmt.Errorf("agent %s cannot be launched for fix sessions", agentName)
72		}
73		cmd, err := launcher.LaunchCmd(ctx, prompt)
74		if err != nil {
75			return fmt.Errorf("build fix command: %w", err)
76		}
77		cmd.Env = withoutReviewOrInvestigateEnv(cmd.Env)
78		if len(cmd.Env) == 0 {
79			cmd.Env = withoutReviewOrInvestigateEnv(os.Environ())
80		}
81		if err := cmd.Run(); err != nil {
82			if errors.Is(err, context.Canceled) {
83				return fmt.Errorf("fix agent cancelled: %w", err)
84			}
85			var exitErr *exec.ExitError
86			if errors.As(err, &exitErr) {
87				return fmt.Errorf("fix agent exited with status %d: %w", exitErr.ExitCode(), err)
88			}
89			return fmt.Errorf("run fix agent: %w", err)
90		}
91		return nil
92	}
